import{_ as t,o as d,c as a,a4 as s}from"./chunks/framework.Dsbb2oA0.js";const m=JSON.parse('{"title":"CAD 图纸操作 · 后端 MxServiceCode 指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/9.AIManual/3.BackendMxServiceCodeGuide.md","filePath":"zh/docs/9.AIManual/3.BackendMxServiceCodeGuide.md"}'),o={name:"zh/docs/9.AIManual/3.BackendMxServiceCodeGuide.md"};function n(c,e,r,i,l,p){return d(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="cad-图纸操作-·-后端-mxservicecode-指南" tabindex="-1">CAD 图纸操作 · 后端 MxServiceCode 指南 <a class="header-anchor" href="#cad-图纸操作-·-后端-mxservicecode-指南" aria-label="Permalink to &quot;CAD 图纸操作 · 后端 MxServiceCode 指南&quot;">​</a></h1><blockquote><p>适用范围：服务端处理 CAD 图纸（Node.js 命令行：格式转换、数据提取、参数化绘图生成、切分合并、批量导出）。 路由规则见 <a href="./1.EntryGuide.html">入口指引</a>；前端操作见 <a href="./2.FrontendMxCadGuide.html">前端 mxcad 指南</a>。</p></blockquote><p><strong>目录</strong></p><ul><li><a href="#一mxservicecode-是什么">一、MxServiceCode 是什么</a></li><li><a href="#二程序获取与目录结构">二、程序获取与目录结构</a></li><li><a href="#三本地参考文档必读">三、本地参考文档（必读）</a></li><li><a href="#四任务命令选型速查">四、任务→命令选型速查</a></li><li><a href="#五任务文档检索指引">五、任务→文档检索指引</a></li><li><a href="#六能力边界说明">六、能力边界说明</a></li></ul><hr><h2 id="一、mxservicecode-是什么" tabindex="-1">一、MxServiceCode 是什么 <a class="header-anchor" href="#一、mxservicecode-是什么" aria-label="Permalink to &quot;一、MxServiceCode 是什么&quot;">​</a></h2><p>MxServiceCode 是一个<strong>独立的 Node.js 命令行工程</strong>，用于在后台处理 CAD 图纸文件：打开/保存 DWG、格式转换、数据提取、参数化绘图生成新图纸、按图框批量切图、合并比较、导出 PDF 等。</p><p>工作方式：<strong>命令行调用，执行完即退出，无守护进程，无需启动任何服务</strong>。入口是 <code>mxapp.js</code>，每次执行一个命令，stdout 输出一行 JSON 结果；工程内置 Node 运行时，不依赖系统 Node。</p><p><strong>后端服务 zip 的内容</strong>（同时含后端服务与格式转换程序 mxcadassembly，即完整超集；若只需转换程序可改下单独 MxConvert 包，见 <a href="./1.EntryGuide.html">入口指引</a>&quot;链接清单&quot;）：</p><p><strong>Windows（后端服务包解压后只有一个顶层目录 <code>MxServiceCode_TryVersion\\</code>，其下两个子目录）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxServiceCode_TryVersion\\    ← 解压后的顶层目录（与 zip 同名）</span></span>
<span class="line"><span>├── MxServiceCode\\</span></span>
<span class="line"><span>│   ├── NODE.JS后台程序开发.doc   ← 官方教程：教如何基于本工程做后台开发（不是 API 文档）</span></span>
<span class="line"><span>│   ├── MxServiceCode.sln        ← 解决方案文件</span></span>
<span class="line"><span>│   └── MxServiceCode\\           ← 工程目录（所有命令在此目录执行）</span></span>
<span class="line"><span>│       ├── bin\\node.exe          ← 内置 Node 运行时</span></span>
<span class="line"><span>│       ├── Mx2DNode.node         ← 原生模块（核心 CAD 能力）</span></span>
<span class="line"><span>│       ├── mxapp.js              ← 入口（命令行）</span></span>
<span class="line"><span>│       ├── package.json          ← npm run build 编译</span></span>
<span class="line"><span>│       ├── src\\                  ← TS 源码（mxcad\\ 为 API 类，sample\\ 为功能示例，MxCommand.ts 为命令注册）</span></span>
<span class="line"><span>│       ├── test.bat              ← 测试脚本</span></span>
<span class="line"><span>│       ├── empty_template.dwg    ← 空白模板</span></span>
<span class="line"><span>│       ├── A3.dwg / BT.DWG       ← 图框 / 图签示例图块</span></span>
<span class="line"><span>│       └── t1.dwg / tree.dwg     ← 测试图纸</span></span>
<span class="line"><span>└── MxCAD\\</span></span>
<span class="line"><span>    └── Release\\                 ← 格式转换程序目录（mxcadassembly.exe + fonts\\ + 运行依赖等）</span></span></code></pre></div><p><strong>Linux（后端服务包解压后只有一个顶层目录 <code>MxServiceCode_TryVersion\\</code>，其下两个子目录）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxServiceCode_TryVersion\\    ← 解压后的顶层目录（与 zip 同名）</span></span>
<span class="line"><span>├── MxServiceCode\\</span></span>
<span class="line"><span>│   ├── NODE.JS后台程序开发.doc   ← 官方教程</span></span>
<span class="line"><span>│   └── MxServiceCode\\           ← 工程目录（无 .sln；内置运行时为 node 而非 bin\\node.exe，</span></span>
<span class="line"><span>│                                 另含 start_demo_MxServiceCode.sh、start_demo_systemlib_MxServiceCode.sh、Linux启动说明.txt）</span></span>
<span class="line"><span>└── Linux\\</span></span>
<span class="line"><span>    └── MxCAD\\                   ← 格式转换程序目录（mxcadassembly + fonts\\ + 运行依赖等）</span></span></code></pre></div><h2 id="二、程序获取与目录结构" tabindex="-1">二、程序获取与目录结构 <a class="header-anchor" href="#二、程序获取与目录结构" aria-label="Permalink to &quot;二、程序获取与目录结构&quot;">​</a></h2><h3 id="_2-1-下载与放置-固定临时路径-只下载一次-跨会话复用" tabindex="-1">2.1 下载与放置（固定临时路径，只下载一次，跨会话复用） <a class="header-anchor" href="#_2-1-下载与放置-固定临时路径-只下载一次-跨会话复用" aria-label="Permalink to &quot;2.1 下载与放置（固定临时路径，只下载一次，跨会话复用）&quot;">​</a></h3><p><strong>下载地址以 <a href="./1.EntryGuide.html">入口指引</a> 的&quot;链接清单&quot;为准</strong>（按目标机器平台取&quot;后端服务&quot;对应行；Linux 包为 Ubuntu 20.04 x86_64 构建）。试用版，注意授权有效期。</p><p><strong>固定临时路径</strong>：Windows = <code>%TEMP%\\MxCAD\\</code>，Linux = <code>/tmp/MxCAD/</code>。按 <a href="./1.EntryGuide.html">入口指引</a> 的排查步骤执行：先判断任务需要什么（仅转换程序 / 需要后端服务），再查看临时路径下有什么——什么都没有 → 按需要下载对应 zip（只需转换程序 → 单独 MxConvert 包；需要后端服务 → MxServiceCode 包，内含转换程序）解压到临时路径；只有转换程序 → 仅需转换程序时做过期检测（见《部署与启动说明.md》）即可用，需要后端时清空重下后端包；已解包后端包 → 做过期检测 + 完整性验证，不完整清空重下。<strong>重新下载前必须先清空临时路径</strong>（各包目录结构固定，后端包是完整超集）。不要扫描用户机器其他目录；系统清理临时目录后重新下载即可。</p><p><strong>所有命令都在临时路径下的 <code>MxServiceCode\\MxServiceCode</code>（工程目录）中执行。</strong></p><h3 id="_2-2-基本用法-linux-首次使用需先配置权限" tabindex="-1">2.2 基本用法（Linux 首次使用需先配置权限） <a class="header-anchor" href="#_2-2-基本用法-linux-首次使用需先配置权限" aria-label="Permalink to &quot;2.2 基本用法（Linux 首次使用需先配置权限）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_demo_MxServiceCode.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start_demo_MxServiceCode.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 脚本内已完成 node、Mx2DNode.node、mxcadassembly 等的 chmod</span></span></code></pre></div><p>出错时改用 <code>./start_demo_systemlib_MxServiceCode.sh</code>（使用 systemLib 目录下的原生库）。</p><blockquote><p>⚠️ <strong>内置 Node 版本限制（实测）</strong>：<code>bin\\node.exe</code> 为 <strong>v10.9.0</strong>，仅支持 <strong>CommonJS</strong>——ESM（<code>import</code> 语法 / <code>.mjs</code>）直接报 <code>SyntaxError</code>；也没有 <code>fetch</code>、可选链等新特性。用内置 node 写辅助脚本一律用 CommonJS（<code>require</code>）+ <code>.js</code>；需要 ESM 时改用系统 Node。</p></blockquote><h2 id="三、本地参考文档-必读" tabindex="-1">三、本地参考文档（必读） <a class="header-anchor" href="#三、本地参考文档-必读" aria-label="Permalink to &quot;三、本地参考文档（必读）&quot;">​</a></h2><table><thead><tr><th>文档</th><th>内容</th><th>何时读</th></tr></thead><tbody><tr><td><a href="./4.BackendReferenceDocs/1.MxServiceCodeCommandReference.html">MxServiceCode命令参考.md</a></td><td>12 个 CLI 命令完整参考（参数/返回值/调用示例）+ fileparam JSON 传参 + 新命令注册方法</td><td>调用现成命令时</td></tr><tr><td><a href="./4.BackendReferenceDocs/2.Mx2DNodeSecondaryDevAPIReference.html">Mx2DNode二开API参考.md</a></td><td>后台参数化绘图/数据提取全部 API（Mx2DDraw、MxBackstage、McDbDatabase、McDb* 实体、选择集、几何对象）</td><td>二开新命令/定制逻辑时</td></tr><tr><td><a href="./4.BackendReferenceDocs/3.DeploymentAndStartup.html">部署与启动说明.md</a></td><td>目录结构、调用方式、Linux 权限、mxcadassembly 独立调用与有效期检测、日志、二开工作流</td><td>部署/排错时</td></tr><tr><td><a href="./4.BackendReferenceDocs/4.SvgDwgKitGuide.html">SVG⇄DWG 转换套件指南.md</a></td><td>mxcad-svg-dwg-kit 工具包：SVG⇄DWG 双向所见即所得转换（获取、CLI 契约、参数表、自检、修改方法闭环）</td><td>涉及 SVG↔DWG 转换时（mxcadassembly 不支持 SVG）</td></tr></tbody></table><h2 id="四、任务→命令选型速查" tabindex="-1">四、任务→命令选型速查 <a class="header-anchor" href="#四、任务→命令选型速查" aria-label="Permalink to &quot;四、任务→命令选型速查&quot;">​</a></h2><p><strong>调用任何现成命令前，先对照本表确认&quot;该命令的契约是否覆盖需求&quot;——命令名不是选型依据。</strong> 现成命令不覆盖时直接走二开（见《Mx2DNode二开API参考.md》第九节范例），不要拿功能不符的命令&quot;跑一下试试&quot;。</p><table><thead><tr><th>想做的事</th><th>走哪条路</th><th>备注</th></tr></thead><tbody><tr><td>提取文字 / 块属性</td><td><code>getcaddata</code>（现成）</td><td>⚠️ 仅 TEXT + INSERT 属性，<strong>不含任何几何实体</strong></td></tr><tr><td>提取<strong>指定图层</strong>的多段线顶点</td><td><code>getPolylineTheSpecifiedLayer</code>（现成）</td><td>⚠️ 图层名硬编码在 <code>GetDwgData.ts</code>，跨图纸使用必须先改源码重编译</td></tr><tr><td>提取<strong>直线 / 圆 / 其他几何实体</strong>数据</td><td>二开</td><td>无现成命令；范例见《Mx2DNode二开API参考.md》第九节（<code>modelSpace().getAllEntity()</code> + <code>instanceof McDbXxx</code>）</td></tr><tr><td>提取图层清单</td><td><code>getAllLayer</code>（现成）</td><td>输出 <code>&lt;文件名&gt;_layers.json</code></td></tr><tr><td>DWG→mxweb 转换</td><td><code>mxcadassembly</code> 独立调用</td><td>⚠️ <code>convert</code> 命令已废弃不可用；<code>outpath</code> 目录必须预先存在</td></tr><tr><td>SVG→DWG / DWG→SVG 转换</td><td>新套件 mxcad-svg-dwg-kit（<code>bin\\mxkit.cmd</code> / <code>dist\\mxkit.js</code>）</td><td>⚠️ mxcadassembly 不支持 SVG；见《SVG⇄DWG 转换套件指南.md》</td></tr><tr><td>切图（按图框批量）</td><td><code>frameCut2</code>（现成）</td><td>⚠️ <code>frameCut</code>（v1）依赖 1337 服务，独立版不可用</td></tr><tr><td>整图导出 PDF</td><td><code>Mx_Custom_ExportPdf</code>（现成）</td><td>自动按图幅缩放</td></tr><tr><td>合并多张 DWG</td><td><code>margeDwg</code>（现成）</td><td>可按图层过滤</td></tr><tr><td>比较两图纸图块表</td><td><code>compare_dwg</code>（现成）</td><td></td></tr><tr><td>参数化绘图（生成新图纸）</td><td>二开（<code>testParamDraw</code> 可当起点模板）</td><td>见《Mx2DNode二开API参考.md》第二、九节</td></tr><tr><td>读/写扩展数据（xdata）</td><td>二开</td><td><code>mxtest_getxdata</code> 仅调试示例（硬编码路径，勿用于生产）</td></tr></tbody></table><h2 id="五、任务→文档检索指引" tabindex="-1">五、任务→文档检索指引 <a class="header-anchor" href="#五、任务→文档检索指引" aria-label="Permalink to &quot;五、任务→文档检索指引&quot;">​</a></h2><table><thead><tr><th>任务类型</th><th>应读文档</th></tr></thead><tbody><tr><td>调用现成命令（转换/提取数据/切图/合并/导出 PDF/图层/比较图纸）</td><td>《MxServiceCode命令参考.md》</td></tr><tr><td>二开：新增命令或定制处理逻辑</td><td>《Mx2DNode二开API参考.md》+ 工程 <code>src\\sample\\</code> 示例代码</td></tr><tr><td>环境部署 / 启动失败 / Linux 权限 / 日志排查</td><td>《部署与启动说明.md》</td></tr><tr><td>格式转换参数（DWG/DXF/MXWEB/PDF/JPG、cut_dwg、print_to_pdf）</td><td>官方《图纸转换程序使用教程》：<a href="./../8.RelatedArticles/1.IntroductionGuide/3.Drawing Conversion Function Usage Guide.html">链接</a></td></tr><tr><td>SVG↔DWG 互转（含 SVG→mxweb 链路）</td><td>《SVG⇄DWG 转换套件指南.md》（./4.BackendReferenceDocs/4.SvgDwgKitGuide.md）</td></tr><tr><td>后台开发入门</td><td>随包附带的 <code>NODE.JS后台程序开发.doc</code>（教如何基于本工程开发，非 API 文档）</td></tr></tbody></table><h2 id="六、能力边界说明-基于-1-0-试用版实测" tabindex="-1">六、能力边界说明（基于 1.0 试用版实测） <a class="header-anchor" href="#六、能力边界说明-基于-1-0-试用版实测" aria-label="Permalink to &quot;六、能力边界说明（基于 1.0 试用版实测）&quot;">​</a></h2><p><strong>已具备能力</strong></p><ul><li>DWG/DXF 打开与保存</li><li>格式转换：DWG→mxweb 等（经 <code>mxcadassembly</code> 独立调用，见《部署与启动说明.md》第三节）</li><li>参数化绘图：线、圆弧、圆、椭圆、点、文字、多行文字、图片、填充、图块、图框图签、五种标注</li><li>数据提取：文字、块属性、多段线、图层、xdata 扩展数据</li><li>选择集与过滤（按类型/图层/窗口/交越）</li><li>实体编辑：属性、xdata、分解（explode）、求交（intersectWith）、面积（getArea）</li><li>图纸合并（可按图层过滤）、按图框批量切图、图纸比较</li><li>导出：PDF、JPG、mxweb（前端显示格式）</li><li>系统变量读写（LTSCALE 等）</li></ul><p><strong>开发模式约定</strong></p><ul><li>后续新增 CAD 接口功能：由 AI 基于本工程开发（<code>src\\sample\\</code> 模式 + Mx2DNode API）</li><li>修改源码后必须 <code>npm run build</code> 重新编译（运行的是 .js）</li></ul><p><strong>限制</strong></p><ul><li><code>convert</code> 命令不可用：其输出的 wgh 格式已废弃，原生模块已移除 <code>writeWebGLFile</code>（运行报 <code>code:-4</code>）。mxcad 前端只认 mxweb，DWG→mxweb 直接用 <code>mxcadassembly</code>（见《MxServiceCode命令参考.md》详解 1）</li><li><code>frameCut</code>（v1）命令依赖 1337 端口服务，独立版 MxServiceCode 不提供该服务，<strong>请使用 <code>frameCut2</code></strong>（直接调用 mxcadassembly，功能等价）</li><li>试用版（TryVersion）：注意授权有效期与打开次数限制</li><li><code>mxtest_getxdata</code> 等调试命令含硬编码路径，不可直接用于生产</li><li><code>getPolylineTheSpecifiedLayer</code> 的图层过滤值硬编码在源码中，使用前需按目标图纸修改</li><li><strong>不支持 SVG</strong>：mxcadassembly 的 <code>outname</code> 只接受 <code>.mxweb/.dwg/.dxf/.pdf/.jpg</code>，任何 SVG 输入/输出都不在其能力范围内；SVG⇄DWG 互转走 mxcad-svg-dwg-kit 新工具包（见《SVG⇄DWG 转换套件指南.md》）</li></ul>`,36)])])}const x=t(o,[["render",n]]);export{m as __pageData,x as default};
